changeSet.sql:
CREATE OR REPLACE FUNCTION nexus.aspect_queue_rows_unscoped() RETURNS bigint
LANGUAGE plpgsql
AS $fn$
DECLARE
    v_forced boolean;
    v_rows   bigint;
BEGIN
    SELECT c.relforcerowsecurity INTO v_forced
      FROM pg_class c
     WHERE c.oid = to_regclass('nexus.aspect_extraction_queue');
    IF NOT FOUND THEN
        RETURN 0;
    END IF;
    ALTER TABLE nexus.aspect_extraction_queue NO FORCE ROW LEVEL SECURITY;
    SELECT count(*) INTO v_rows FROM nexus.aspect_extraction_queue;
    IF v_forced THEN
        ALTER TABLE nexus.aspect_extraction_queue FORCE ROW LEVEL SECURITY;
    END IF;
    RETURN v_rows;
END
$fn$;

REVOKE ALL ON FUNCTION nexus.aspect_queue_rows_unscoped() FROM PUBLIC;

DO $fk$
BEGIN
    IF to_regclass('nexus.aspect_extraction_queue') IS NOT NULL THEN
        ALTER TABLE nexus.aspect_extraction_queue DROP CONSTRAINT IF EXISTS aspect_extraction_queue_collection_fk;
        ALTER TABLE nexus.aspect_extraction_queue
            ADD CONSTRAINT aspect_extraction_queue_collection_fk
            FOREIGN KEY (tenant_id, collection)
            REFERENCES nexus.catalog_collections (tenant_id, name)
            ON DELETE CASCADE ON UPDATE CASCADE
            NOT VALID;
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_constraint WHERE conname = 'aspect_extraction_queue_collection_fk') THEN
                ALTER TABLE nexus.aspect_extraction_queue VALIDATE CONSTRAINT aspect_extraction_queue_collection_fk;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            RAISE WARNING 'aspect_extraction_queue_collection_fk left NOT VALID: %', SQLERRM;
        END;
    END IF;
END
$fk$;

