DROP FUNCTION IF EXISTS nexus.aspect_queue_rows_unscoped();

changeSet.sql:
DO $drop$
DECLARE
    v_rows bigint;
BEGIN
    v_rows := nexus.aspect_queue_rows_unscoped();
    IF v_rows <> 0 THEN
        RAISE EXCEPTION 'nexus.aspect_extraction_queue holds % row(s); aspects-005-2 does not drop it and is retried at the next boot', v_rows;
    END IF;
    DROP TABLE IF EXISTS nexus.aspect_extraction_queue;
    DROP FUNCTION IF EXISTS nexus.aspect_queue_rows_unscoped();
END
$drop$;

